{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/feature-rows.json
    The features as rows: text beside a picture (the rows layout of FeatureGrid). Icons are Lucide names.
    Props (p): features, mediaSide. *}
{var $v_features = ($p['features'] ?? null)}
{var $v_mediaSide = ($p['mediaSide'] ?? 'end')}
{capture $c_6}
  {foreach og_l($v_features) as $v_feature}
    {capture $c_5}
      {capture $c_3}
        {=og_include('icons/LucideIcon.latte', ['name' => og_s(og_get($v_feature, ['icon'])), 'size' => 24])|noescape}
        {capture $c_1}
          {=og_text(og_get($v_feature, ['title']))}
        {/capture}
        {=og_include('compose/Title.latte', ['as' => 3, 'size' => 'xl', 'weight' => 'bold', 'children' => (string) $c_1])|noescape}
        {capture $c_2}
          {=og_text(og_get($v_feature, ['text']))}
        {/capture}
        {=og_include('compose/Text.latte', ['size' => 'base', 'class' => 'text-muted-foreground', 'children' => (string) $c_2])|noescape}
      {/capture}
      {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => 'min-w-0', 'children' => (string) $c_3])|noescape}
      {capture $c_4}
        {=og_include('blocks/media-frame.latte', ['p' => ['alt' => og_get($v_feature, ['title']), 'ratio' => '4/3']])|noescape}
      {/capture}
      {=og_include('compose/Box.latte', ['class' => og_s(og_cnv(['w-full min-w-0', (og_t(og_eq($v_mediaSide, 'start')) ? 'md:order-first' : (og_t(og_eq($v_mediaSide, 'alternate')) ? 'md:group-even:order-first' : ''))])), 'children' => (string) $c_4])|noescape}
    {/capture}
    {=og_include('compose/Grid.latte', ['cols' => '1-2', 'class' => 'group items-center gap-8', 'attrs' => og_attrs(['data-slot', 'feature-card']), 'children' => (string) $c_5])|noescape}
  {/foreach}
{/capture}
{=og_include('compose/Stack.latte', ['gap' => '8', 'align' => 'stretch', 'attrs' => og_attrs(['data-slot', 'feature-rows']), 'children' => (string) $c_6])|noescape}
